package com.jnapanam.sportszone.membership.service;
import com.jnapanam.sportszone.catalog.model.Sport; import com.jnapanam.sportszone.catalog.repository.SportRepository; import com.jnapanam.sportszone.common.exception.*; import com.jnapanam.sportszone.identity.model.User; import com.jnapanam.sportszone.identity.repository.UserRepository; import com.jnapanam.sportszone.membership.dto.*; import com.jnapanam.sportszone.membership.model.*; import com.jnapanam.sportszone.membership.repository.*; import java.time.*; import java.util.*;import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class MembershipService{
 private com.jnapanam.sportszone.payment.subscription.RecurringSubscriptionService recurringSubscriptions;
 @org.springframework.beans.factory.annotation.Autowired(required=false)
 public void setRecurringSubscriptions(com.jnapanam.sportszone.payment.subscription.RecurringSubscriptionService service){this.recurringSubscriptions=service;}
 private final MembershipPlanRepository plans;private final CustomerMembershipRepository memberships;private final SportRepository sports;private final UserRepository users;private final long paymentMinutes;
 public MembershipService(MembershipPlanRepository p,CustomerMembershipRepository m,SportRepository s,UserRepository u,@Value("${app.payment.pending-minutes:15}")long paymentMinutes){plans=p;memberships=m;sports=s;users=u;this.paymentMinutes=paymentMinutes;}
 @Transactional(readOnly=true) public List<MembershipPlanResponse> publicPlans(){return plans.findByStatusOrderByPriceAscNameAsc(MembershipPlanStatus.ACTIVE).stream().map(MembershipPlanResponse::from).toList();}
 @Transactional(readOnly=true) public List<MembershipPlanResponse> allPlans(){return plans.findAllByOrderByPriceAscNameAsc().stream().map(MembershipPlanResponse::from).toList();}
 @Transactional public MembershipPlanResponse create(MembershipPlanRequest r){if(plans.existsByCodeIgnoreCase(r.code()))throw new ConflictException("Membership plan code already exists");return MembershipPlanResponse.from(plans.save(new MembershipPlan(r.code(),r.name(),r.description(),r.durationDays(),r.price(),r.dailyBookingLimit(),r.monthlyBookingLimit(),resolveSports(r.sportCodes()))));}
 @Transactional public MembershipPlanResponse update(UUID id,MembershipPlanRequest r){MembershipPlan p=plan(id);if(!p.getCode().equalsIgnoreCase(r.code()))throw new BadRequestException("Membership plan code cannot be changed");p.update(r.name(),r.description(),r.durationDays(),r.price(),r.dailyBookingLimit(),r.monthlyBookingLimit(),resolveSports(r.sportCodes()));return MembershipPlanResponse.from(p);}
 @Transactional public MembershipPlanResponse status(UUID id,PlanStatusRequest r){MembershipPlan p=plan(id);p.status(r.status());return MembershipPlanResponse.from(p);}
 @Transactional public CustomerMembershipResponse subscribe(UUID userId,SubscribeRequest r){User u=user(userId);MembershipPlan p=plans.findByCodeIgnoreCase(r.planCode()).orElseThrow(()->new NotFoundException("Membership plan not found"));if(p.getStatus()!=MembershipPlanStatus.ACTIVE)throw new ConflictException("Membership plan is not available");if(memberships.existsByUserIdAndPlanIdAndStatusIn(userId,p.getId(),List.of(MembershipStatus.PENDING_PAYMENT,MembershipStatus.ACTIVE,MembershipStatus.SUSPENDED)))throw new ConflictException("Customer already has an open membership for this plan");boolean paymentRequired=p.getPrice().signum()>0;return CustomerMembershipResponse.from(memberships.save(new CustomerMembership(u,p,paymentRequired,Instant.now().plusSeconds(paymentMinutes*60))));}
 @Transactional public List<CustomerMembershipResponse> mine(UUID userId){expire();return memberships.findByUserIdOrderBySubscribedAtDesc(userId).stream().map(CustomerMembershipResponse::from).toList();}
 @Transactional public CustomerMembershipResponse cancel(UUID userId,UUID id){CustomerMembership m=membership(id);if(!m.getUser().getId().equals(userId))throw new NotFoundException("Membership not found");if(m.getStatus()==MembershipStatus.CANCELLED||m.getStatus()==MembershipStatus.EXPIRED)throw new ConflictException("Membership cannot be cancelled");if(recurringSubscriptions!=null)recurringSubscriptions.cancelByReference(userId,"MEMBERSHIP",id);if(recurringSubscriptions!=null)recurringSubscriptions.cancelByReference(userId,"MEMBERSHIP",id);m.change(MembershipStatus.CANCELLED,"Cancelled by customer");return CustomerMembershipResponse.from(m);}
 @Transactional public CustomerMembershipResponse adminAction(UUID id,MembershipActionRequest r){CustomerMembership m=membership(id);if(r.status()==MembershipStatus.ACTIVE){if(m.getStatus()!=MembershipStatus.PENDING_PAYMENT&&m.getStatus()!=MembershipStatus.SUSPENDED)throw new ConflictException("Only pending or suspended memberships can be activated");m.activate(r.startDate()==null?LocalDate.now():r.startDate());}else if(r.status()==MembershipStatus.SUSPENDED||r.status()==MembershipStatus.CANCELLED){
  if(recurringSubscriptions!=null)recurringSubscriptions.cancelByReference(m.getUser().getId(),"MEMBERSHIP",id);
  m.change(r.status(),r.reason());
}else throw new BadRequestException("Admin action supports ACTIVE, SUSPENDED or CANCELLED");return CustomerMembershipResponse.from(m);}
 @Transactional public List<CustomerMembershipResponse> allMemberships(){expire();return memberships.findAllByOrderBySubscribedAtDesc().stream().map(CustomerMembershipResponse::from).toList();}
 private void expire(){for(CustomerMembership m:memberships.findAll())if(m.getStatus()==MembershipStatus.ACTIVE&&m.getEndDate()!=null&&m.getEndDate().isBefore(LocalDate.now()))m.change(MembershipStatus.EXPIRED,"Membership period completed");}
 @Transactional public int cleanupUnpaid(){int count=0;for(CustomerMembership m:memberships.findByStatusAndPaymentExpiresAtLessThanEqual(MembershipStatus.PENDING_PAYMENT,Instant.now())){if(recurringSubscriptions!=null)recurringSubscriptions.cancelByReference(m.getUser().getId(),"MEMBERSHIP",m.getId());
 m.change(MembershipStatus.EXPIRED,"Payment window expired");count++;}return count;}
 private Set<Sport> resolveSports(Set<String> codes){Set<Sport> result=new LinkedHashSet<>();for(String c:codes)result.add(sports.findByCodeIgnoreCase(c).orElseThrow(()->new NotFoundException("Sport not found: "+c)));return result;}
 private MembershipPlan plan(UUID id){return plans.findById(id).orElseThrow(()->new NotFoundException("Membership plan not found"));} private CustomerMembership membership(UUID id){return memberships.findById(id).orElseThrow(()->new NotFoundException("Membership not found"));} private User user(UUID id){return users.findById(id).orElseThrow(()->new UnauthorizedException("User not found"));}
}
